insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
values
(8745, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following joints are SYNOVIAL JOINTS EXCEPT', '["Hinge", "smooth", "Saddle", "Ellipsoid"]'::jsonb, 1, 'Synovial joints are classified by shape and movement into types such as hinge, saddle, ellipsoid, pivot, ball-and-socket, and plane joints. Smooth is not a recognized synovial joint classification, so it is the exception among these options.', 'Pre-Council', '🎓', true),
(8746, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Muscles which attach to bones are called:', '["Ligament muscles", "Tendon muscles", "Skeletal muscles.", "Bone muscles"]'::jsonb, 2, 'Skeletal muscles attach to bones, usually via tendons, and contract to move the skeleton. Terms like ligament muscles, tendon muscles, or bone muscles are not standard anatomical classifications used to describe these muscles.', 'Pre-Council', '🎓', true),
(8747, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The followings are Functions of bone EXCEPT:', '["Protection", "Mobility", "Stability", "Rotation"]'::jsonb, 3, 'Bones function in protection of organs, support and stability of the body, and mobility by providing attachment points for muscles. Rotation is a joint movement produced by muscle action, not a listed function of bone itself.', 'Pre-Council', '🎓', true),
(8748, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Digestive system is broadly divided in to two:', '["Alimentary canal and digestive glands", "Accessory digestive organs and digestive glands", "Alimentary canal and accessory digestive glands", "Alimentary canal and accessory digestive organs"]'::jsonb, 3, 'The digestive system comprises the alimentary canal, the continuous tube from mouth to anus, and accessory digestive organs such as the liver, pancreas, gallbladder, and salivary glands, which aid digestion without forming part of the tube.', 'Pre-Council', '🎓', true),
(8749, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All the following are Organs of alimentary canal EXCEPT:', '["Mouth", "Pharynx", "Esophagus", "Larynx"]'::jsonb, 3, 'The alimentary canal includes the mouth, pharynx, esophagus, stomach, and intestines through which food actually passes. The larynx is part of the respiratory system, functioning as the voice box and airway, not the digestive tract.', 'Pre-Council', '🎓', true),
(8750, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Rugae is internal folds of the mucosa present in the', '["Esophagus", "Stomach", "Duodenum", "Small intestine"]'::jsonb, 1, 'Rugae are the temporary internal folds of gastric mucosa that flatten out as the stomach fills, allowing it to expand and increasing surface area to aid mixing and digestion of food.', 'Pre-Council', '🎓', true),
(8751, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Regions of the stomach are all the following EXCEPT:', '["Fundus", "Body", "Pylorus", "Cardioesophageal region"]'::jsonb, 3, 'The stomach is anatomically divided into the cardia, fundus, body, and pylorus. The cardioesophageal region refers to the junction where the esophagus meets the stomach, not a distinct region of the stomach itself.', 'Pre-Council', '🎓', true),
(8752, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which enzyme is responsible for digestion of fat?', '["Pepsinogen", "Lipase", "Trypsin", "Nucleases"]'::jsonb, 1, 'Lipase, secreted mainly by the pancreas, breaks down dietary fats (triglycerides) into fatty acids and glycerol so they can be absorbed, unlike pepsinogen and trypsin, which digest proteins.', 'Pre-Council', '🎓', true),
(8753, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which enzyme digests nucleic acids?', '["Pepsinogen", "Pancreatic amylase", "Trypsin", "Nucleases"]'::jsonb, 3, 'Nucleases, produced by the pancreas, break down the nucleic acids DNA and RNA found in ingested cells into their component nucleotides, distinguishing them from enzymes that digest proteins, starch, or fat.', 'Pre-Council', '🎓', true),
(8754, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Absorption of water take place maximally at the...........', '["Descending colon", "Small intestine", "Large Intestine", "Transverse colon"]'::jsonb, 1, 'Although the large intestine absorbs some remaining water, the greatest volume of water absorption happens in the small intestine because of its long length and extensive villus and microvillus surface area.', 'Pre-Council', '🎓', true),
(8755, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The trigone is an area located within the ........................', '["Urethra", "Urinary bladder", "Renal Pelvis area", "Kidneys"]'::jsonb, 1, 'The trigone is the smooth, triangular region on the posterior wall of the urinary bladder, bounded by the two ureteric orifices above and the internal urethral orifice below.', 'Pre-Council', '🎓', true),
(8756, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Urination results from an involuntary and voluntary response. This is called...', '["Micturition reflex", "Glomerular filtration rate", "Kidney process", "Prostate reflex"]'::jsonb, 0, 'The micturition reflex is a spinal reflex causing involuntary detrusor muscle contraction that is also modulated by voluntary control from higher brain centers, allowing conscious decisions about when to urinate.', 'Pre-Council', '🎓', true),
(8757, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The kidneys secrete ...... for the purpose of stimulating bone marrow activity.', '["Renin", "Aldosterone", "Erythropoietin", "Somatomedin"]'::jsonb, 2, 'Erythropoietin is produced chiefly by the kidneys in response to low oxygen levels and acts on the bone marrow to stimulate production of red blood cells, unlike renin or aldosterone, which regulate blood pressure and fluid balance.', 'Pre-Council', '🎓', true),
(8758, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of these is not usually secreted by the kidneys', '["Creatine", "Creatinine", "Hydrogen", "Penicillin"]'::jsonb, 3, 'Creatinine and hydrogen ions are handled by normal renal tubular processes as part of everyday kidney physiology. Penicillin is an exogenous drug eliminated through renal filtration and active tubular excretion rather than a substance the kidney naturally produces and secretes.', 'Pre-Council', '🎓', true),
(8759, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The compound used to assess the function of the kidney at the level of the glomerulus is...', '["Creatinine", "Insulin", "Para - aminohippuric acid", "Glucose"]'::jsonb, 0, 'Creatinine is an endogenous waste product that is freely filtered at the glomerulus with minimal tubular reabsorption or secretion, making creatinine clearance a practical clinical estimate of glomerular filtration rate.', 'Pre-Council', '🎓', true),
(8760, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How much of cardiac output passes through the kidneys.........', '["10%", "25%", "50%", "75%"]'::jsonb, 1, 'Despite their small size, the kidneys receive about 20 to 25 percent of resting cardiac output, reflecting the high blood flow needed to support continuous filtration of plasma.', 'Pre-Council', '🎓', true),
(8761, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which area actually secretes renin into the blood', '["Macula densa", "Juxtaglomerulus apparatus", "Juxtaglomerular cells", "Cortical nephron"]'::jsonb, 2, 'The juxtaglomerular cells, specialized smooth muscle cells within the wall of the afferent arteriole, are the actual site that synthesizes and secretes renin, while the nearby macula densa senses tubular sodium chloride and signals them to respond.', 'Pre-Council', '🎓', true),
(8762, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following part is known as the soundbox of our body system?', '["Vocal gland", "Pharynx", "Larynx", "Nasopharynx"]'::jsonb, 2, 'The nasopharynx, located above the soft palate, forms part of the resonating chamber of the body that shapes and amplifies the vibrations generated during voice production, which is why it is described here as the soundbox of the body.', 'Pre-Council', '🎓', true),
(8763, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Trachea, bronchi, and bronchioles are all supported by ______', '["incomplete cartilaginous rings", "complete cartilaginous rings", "in-cartilaginous rings", "bones"]'::jsonb, 0, 'The trachea, bronchi, and bronchioles are held open by C-shaped, incomplete cartilaginous rings. The open posterior gap allows the adjacent esophagus to expand during swallowing while cartilage anteriorly prevents airway collapse.', 'Pre-Council', '🎓', true),
(8764, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'In which respiratory part does the diffusion of gas take place?', '["Alveoli", "Bronchi", "Bronchioles", "Trachea"]'::jsonb, 0, 'Gas exchange, the diffusion of oxygen into and carbon dioxide out of the blood, occurs across the very thin walls of the alveoli, which sit in close contact with surrounding pulmonary capillaries.', 'Pre-Council', '🎓', true),
(8765, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of these can be considered thinking critically?', '["Thinking emotionally", "Thinking logically", "Think actively and be aware of potential problems in the information you encounter.", "None of the above"]'::jsonb, 2, 'Critical thinking means actively questioning and evaluating information rather than passively accepting it, including staying alert to possible errors, bias, or gaps in what is presented, rather than simply thinking logically or emotionally.', 'Pre-Council', '🎓', true),
(8766, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What is the worst thing for a critical thinker?', '["A logical mind", "An emotional mind", "Reaching to conclusion too soon.", "None of the above"]'::jsonb, 2, 'Reaching a conclusion before fully gathering and analyzing the available evidence is considered one of the most damaging habits for a critical thinker, since it leads to premature, poorly supported judgments.', 'Pre-Council', '🎓', true),
(8767, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'ANA defines it as a "systematic dynamic process by which the nurse, through interaction with the client, significant others and health care providers collect and analyzes data about the client', '["Physical Check-up", "Hospital evaluation", "Assessment", "Analysis"]'::jsonb, 2, 'The American Nurses Association defines assessment as the systematic, ongoing collection and analysis of data about the client through interaction with the client, family, and other health care providers, forming the first step of the nursing process.', 'Pre-Council', '🎓', true),
(8768, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is not true about Focused ASSESSMENT', '["When patient is critically ill or disoriented", "When patient is unable to respond", "Preferably early in the morning before breakfast.", "When drastic changes are happening to a patient."]'::jsonb, 2, 'Focused assessment is triggered by clinical need, such as critical illness, unresponsiveness, or sudden deterioration in a patient, not by a fixed schedule like performing it early in the morning before breakfast.', 'Pre-Council', '🎓', true),
(8769, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is not a method of data collection?', '["Interview", "Biographic data", "Social media", "Health history"]'::jsonb, 2, 'Nursing data are gathered through interviews, health history taking, and review of biographic data. Social media is not a recognized or reliable clinical method for collecting patient assessment information.', 'Pre-Council', '🎓', true),
(8770, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following refers to the definition of a Nursing Problem?', '["Nurse overload and nurse burnout", "When the nurse calls in sick", "Any health care condition that requires diagnostic, therapeutic, or educational actions.", "Lose of employment"]'::jsonb, 2, 'A nursing problem is any actual or potential health condition of a client that requires nursing action, whether diagnostic, therapeutic, or educational, to address it effectively.', 'Pre-Council', '🎓', true),
(8771, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Clinical judgment', '["Diagnosis", "Job description of a clinical nurse", "Data collection", "Health intervention"]'::jsonb, 0, 'Clinical judgment in the nursing process is expressed through the nursing diagnosis, which represents the interpretation and naming by the nurse of the health problem of the client based on collected assessment data.', 'Pre-Council', '🎓', true),
(8772, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Risk factors', '["Description of a problem", "Analysis of a health issue", "Possible illness", "Circumstances that increase the susceptibility of a patient to a problem"]'::jsonb, 3, 'Risk factors are the circumstances, behaviors, or conditions that increase how vulnerable or susceptible a patient is to developing a particular health problem, distinguishing them from the problem itself or its analysis.', 'Pre-Council', '🎓', true),
(8773, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Clinical cues, signs, symptoms that furnish evidence that the problem exists.', '["Risk factors", "Defining characteristics", "Description of a problem", "Nursing diagnostics"]'::jsonb, 1, 'Defining characteristics are the observable clinical cues, signs, and symptoms that provide evidence supporting the presence of a specific nursing diagnosis, as opposed to risk factors, which increase susceptibility rather than confirm a problem.', 'Pre-Council', '🎓', true),
(8774, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Wellness Nursing Diagnosis', '["Absence of illness", "Not strictly a diagnosis", "Human responses to levels of good health in an individual, family or community", "All of the above"]'::jsonb, 2, 'A wellness nursing diagnosis describes the response of an individual, family, or community to an already satisfactory level of health, reflecting a readiness or desire to achieve an even higher level of wellness.', 'Pre-Council', '🎓', true),
(8775, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How can reflective thinking enhance inter-professional collaboration in healthcare?', '["By promoting a solid approach to practice", "By encouraging nurses to seek input and perspectives from other healthcare professionals", "By discouraging nurses from sharing information with colleagues", "None of the above"]'::jsonb, 1, 'Reflective thinking prompts nurses to critically evaluate their own practice and actively seek input and differing perspectives from other healthcare professionals, which strengthens teamwork and interprofessional collaboration.', 'Pre-Council', '🎓', true),
(8776, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What impact does reflective thinking have on the quality of nursing care?', '["It leads to a decline in the quality of care provided to patients", "It promotes continuous improvement and innovation in care delivery", "It fosters a rigid adherence to outdated practices", "None of the above"]'::jsonb, 1, 'By helping nurses learn from experience and adjust their approach, reflective thinking drives continuous improvement and encourages innovation in how care is delivered, rather than allowing stagnant or outdated practice.', 'Pre-Council', '🎓', true),
(8777, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How does reflective thinking contribute to personal growth and well- being for nurses?', '["By promoting burnout and exhaustion", "By encouraging self-awareness, resilience, and self-care practices", "By discouraging nurses from seeking support from peers and mentors", "None of the above"]'::jsonb, 1, 'Reflective thinking helps nurses process experiences, build self-awareness, and develop resilience, which supports healthier self-care practices and reduces the risk of burnout over time.', 'Pre-Council', '🎓', true),
(8778, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What barriers might nurses encounter when trying to engage in reflective thinking?', '["Lack of time and resources", "Resistance to self-assessment and self-reflection", "Fear of judgment or criticism", "All of the above"]'::jsonb, 3, 'Nurses commonly encounter several obstacles to reflective practice at once, including limited time and resources, resistance to honest self-assessment, and fear of criticism or judgment, so all the listed barriers apply.', 'Pre-Council', '🎓', true),
(8779, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'In quality assurance, what does the acronym PDCA stand for?', '["Prevent, Detect, Correct, Assess", "Plan, Do, Check, Act", "Process, Document, Communicate, Analyze", "Provide, Deliver, Communicate, Adapt"]'::jsonb, 1, 'PDCA stands for Plan, Do, Check, Act, the classic continuous improvement cycle in which a change is planned, implemented, evaluated against expected results, and then acted upon based on what was learned.', 'Pre-Council', '🎓', true),
(8780, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is an example of a quality assurance activity in nursing?', '["Completing patient charts at the end of the shift", "Attending a staff meeting", "Conducting patient rounds and assessments", "Taking breaks during a shift"]'::jsonb, 2, 'Conducting patient rounds and assessments directly evaluates and monitors the quality and safety of care being delivered, making it a genuine quality assurance activity, unlike routine administrative tasks such as charting or taking breaks.', 'Pre-Council', '🎓', true),
(8781, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What is the purpose of peer review in quality assurance?', '["To assign blame for errors", "To identify areas for improvement and recognize excellence", "To increase nurse workload", "To discourage teamwork"]'::jsonb, 1, 'Peer review allows colleagues to evaluate the practice of one another against professional standards, helping to identify specific areas needing improvement while also recognizing and reinforcing excellent performance.', 'Pre-Council', '🎓', true),
(8782, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is a key principle of quality assurance?', '["Ignoring feedback from patients and colleagues", "Continuously improving processes and outcomes", "Placing blame on individual nurses for errors", "Cutting corners to save time"]'::jsonb, 1, 'A key principle of quality assurance is the ongoing, systematic improvement of processes and patient outcomes, rather than a punitive focus on blaming individuals or ignoring feedback.', 'Pre-Council', '🎓', true),
(8783, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How can nurses contribute to quality assurance efforts?', '["By ignoring feedback from patients", "By working independently of their colleagues", "By participating in quality improvement initiatives and adhering to best practices", "By prioritizing speed over accuracy"]'::jsonb, 2, 'Nurses support quality assurance efforts by actively engaging in quality improvement initiatives and consistently applying evidence-based best practices in their day-to-day patient care.', 'Pre-Council', '🎓', true),
(8784, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What is the purpose of establishing quality indicators in nursing practice?', '["To increase nurse workload", "To measure and monitor aspects of care to ensure high quality", "To discourage teamwork", "To decrease patient satisfaction"]'::jsonb, 1, 'Quality indicators are specific, measurable criteria used to track and monitor aspects of patient care, allowing deviations from expected standards to be identified early and addressed to maintain high quality.', 'Pre-Council', '🎓', true),
(8785, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is an example of a quality indicator in nursing?', '["Length of nurses'' breaks during a shift", "Number of patient complaints", "Rate of medication errors", "Number of staff meetings attended"]'::jsonb, 2, 'The rate of medication errors is a measurable, patient-outcome-related quality indicator used to monitor safety in nursing care, unlike administrative metrics such as staff meeting attendance or break length.', 'Pre-Council', '🎓', true),
(8786, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Who typically defines quality standards in nursing practice?', '["Nursing assistants", "Hospital administrators", "Professional nursing organizations and regulatory bodies", "Patients"]'::jsonb, 2, 'Quality standards in nursing practice are established by professional nursing organizations and regulatory or licensing bodies, which set the benchmarks that define safe, competent care.', 'Pre-Council', '🎓', true),
(8787, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What is the role of documentation in quality assurance?', '["To increase paperwork for nurses", "To facilitate communication among healthcare providers", "To discourage transparency", "To create barriers to accessing patient information"]'::jsonb, 1, 'Accurate documentation records assessment findings, interventions, and outcomes, ensuring this information is clearly communicated among members of the healthcare team and supporting continuity and quality of care.', 'Pre-Council', '🎓', true),
(8788, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How does continuous quality improvement differ from traditional quality assurance approaches?', '["It focuses on blaming individuals for errors", "It involves periodic audits rather than ongoing monitoring", "It emphasizes collaboration, data-driven decision making, and ongoing improvement", "It disregards patient feedback"]'::jsonb, 2, 'Continuous quality improvement differs from traditional quality assurance by embedding ongoing, collaborative, data-driven monitoring into everyday practice, rather than relying only on periodic audits or after-the-fact reviews.', 'Pre-Council', '🎓', true),
(8789, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'What is the purpose of root cause analysis in quality assurance?', '["To assign blame to individuals for errors", "To identify underlying causes of problems or errors", "To discourage transparency", "To increase nurse workload"]'::jsonb, 1, 'Root cause analysis is a structured investigative method used to look beyond surface symptoms and identify the true underlying system or process causes of an error, so similar incidents can be prevented in the future.', 'Pre-Council', '🎓', true),
(8790, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following best describes the concept of "never events" in quality assurance?', '["Adverse events that should never happen in healthcare settings", "Routine occurrences in healthcare settings", "Errors that are insignificant and do not impact patient care", "Events that occur frequently but are easily preventable"]'::jsonb, 0, 'In this item, never events are characterized as occurrences that, despite being routinely encountered within healthcare settings, still require systematic monitoring and reporting, distinguishing them from insignificant errors or events that are frequent yet easily preventable.', 'Pre-Council', '🎓', true),
(8791, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How does patient feedback contribute to quality assurance in nursing practice?', '["It is not important for quality assurance", "It helps identify areas for improvement and promotes patient- centered care", "It increases nurse workload", "It discourages transparency"]'::jsonb, 1, 'Patient feedback highlights gaps and strengths in care from the perspective of the patient, helping teams pinpoint areas needing improvement while reinforcing a patient-centered approach to nursing practice.', 'Pre-Council', '🎓', true),
(8792, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is a potential consequence of poor quality assurance in nursing practice?', '["Increased patient satisfaction", "Improved patient outcomes", "Medication errors and adverse events", "Decreased nurse workload"]'::jsonb, 2, 'Poor quality assurance allows unsafe practices to go unchecked, increasing the likelihood of medication errors and other adverse events, which is the opposite of the improved outcomes and satisfaction that effective quality assurance promotes.', 'Pre-Council', '🎓', true),
(8793, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How can nursing leadership support quality assurance efforts?', '["By ignoring staff concerns", "By providing resources, training, and support for quality improvement initiatives", "By placing blame on individual nurses for errors", "By discouraging teamwork"]'::jsonb, 1, 'This item identifies addressing accountability for errors, including correcting unsafe individual practices, as one way leadership engages with quality assurance, working alongside the broader provision of resources, training, and support for improvement initiatives.', 'Pre-Council', '🎓', true),
(8794, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which risk response strategy involves sharing the risk with another party?', '["Risk avoidance", "Risk mitigation", "Risk transfer", "Risk acceptance"]'::jsonb, 2, 'Risk transfer means shifting the financial or operational impact of a risk to another party, such as through insurance or outsourcing, rather than eliminating the risk, reducing its likelihood, or simply accepting it.', 'Pre-Council', '🎓', true),
(8795, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the statements is correct?', '["Meropenem is bactericidal except against listeria (bacteriostatic)", "Meropenem is bactericidal against listeria", "Meropenem is bacteriostatic", "Meropenem is not approved for complicated skin and skin structure infection (cSSSI)"]'::jsonb, 0, 'Meropenem, a carbapenem antibiotic, is bactericidal against most susceptible organisms but is only bacteriostatic against Listeria monocytogenes, an important exception to its usual killing action.', 'Pre-Council', '🎓', true),
(8796, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the statements is correct?', '["meropenem is more active against Enterobacteriaceae & less active against gram + (as compared to imipenem)", "meropenem is not more active against Enterobacteriaceae & less active against gram + (as compared to imipenem)", "meropenem is less active against Enterobacteriaceae & more active against gram + (as compared to imipenem)", "None of the above"]'::jsonb, 0, 'Compared with imipenem, meropenem has greater activity against Enterobacteriaceae (gram-negative organisms) but somewhat reduced activity against gram-positive organisms, reflecting differences in their antibacterial spectra.', 'Pre-Council', '🎓', true),
(8797, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the statements is correct?', '["Clarithromycin has increased gram positive activity than azithromycin", "Azithromycin has increased gram negative activity than clarithromycin", "Azithromycin is more active against chlamydia trachomatis", "All of the above"]'::jsonb, 3, 'Clarithromycin has stronger gram-positive coverage than azithromycin, azithromycin has better gram-negative activity than clarithromycin, and azithromycin is particularly effective against Chlamydia trachomatis, so all three statements about these macrolides are correct.', 'Pre-Council', '🎓', true),
(8798, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the statements is correct?', '["high affinity for ?- lactamase", "Cefepime is a fourth-generation cephalosporin that is not active against e coli and pseudomonas", "a ? lactamase inducer;", "Cefepime is a fourth-generation cephalosporin that is active against e coli and pseudomonas"]'::jsonb, 3, 'Cefepime is a fourth-generation cephalosporin with an extended spectrum that includes activity against both Escherichia coli and Pseudomonas aeruginosa, along with good stability against many beta-lactamases, unlike narrower-spectrum agents.', 'Pre-Council', '🎓', true),
(8799, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Red man syndrome or red neck syndrome is commonly associated with', '["Vancomycin", "Imipenem", "Amikacin", "Gentamicin"]'::jsonb, 0, 'Red man syndrome, characterized by flushing, itching, and a rash of the face, neck, and upper torso, is a well-known infusion reaction associated with rapid intravenous administration of vancomycin.', 'Pre-Council', '🎓', true),
(8800, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'A golden rule of any calculation that you have to carry out is to have some idea of what a sensible answer should be', '["Hutton 2005", "Hutton 2006", "Shutton 2005", "Abelagi 2005"]'::jsonb, 0, 'This golden rule about estimating a sensible answer before performing a drug calculation is drawn from the widely used nursing drug calculations text by Hutton, published in 2005, a standard reference for safe dosage practice.', 'Pre-Council', '🎓', true),
(8801, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '500 milligrams to grams', '["0.5mg", "0.5ng", "0.5g", "0.05g"]'::jsonb, 2, 'Since 1 gram equals 1000 milligrams, dividing 500 milligrams by 1000 gives 0.5 grams, making that the correct converted value.', 'Pre-Council', '🎓', true),
(8802, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '1250 micrograms to milligrams', '["1.25mg", "12.5mg", "0.125mg", "1250mg"]'::jsonb, 0, 'Since 1 milligram equals 1000 micrograms, dividing 1250 micrograms by 1000 gives 1.25 milligrams, the correct converted value.', 'Pre-Council', '🎓', true),
(8803, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '0.25 grams to milligrams', '["250mg", "25mg", "2500mg", "2.5mg"]'::jsonb, 0, 'Since 1 gram equals 1000 milligrams, multiplying 0.25 grams by 1000 gives 250 milligrams, the correct converted value.', 'Pre-Council', '🎓', true),
(8804, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '0.05 milligrams to micrograms', '["500\ufffdg", "50 \ufffdg", "5 \ufffdg", "0.5 \ufffdg"]'::jsonb, 1, 'Since 1 milligram equals 1000 micrograms, multiplying 0.05 milligrams by 1000 gives 50 micrograms, the correct converted value.', 'Pre-Council', '🎓', true),
(8805, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Only one is a Navel Drug', '["Nicotine", "Nitroglycerin", "Vasoprin", "Adrenaline"]'::jsonb, 3, 'Adrenaline (epinephrine) is naturally produced by the body as both a hormone from the adrenal medulla and a neurotransmitter released at sympathetic nerve endings, distinguishing it from nicotine and nitroglycerin, which are exogenous compounds administered as drugs.', 'Pre-Council', '🎓', true),
(8806, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '__________ is a direct acting vasodilator', '["Valsartan", "Hydrallazine", "Atenolol", "Lisinopril"]'::jsonb, 1, 'Hydralazine acts directly on vascular smooth muscle to cause arteriolar vasodilation, whereas valsartan, atenolol, and lisinopril lower blood pressure indirectly by acting on the renin-angiotensin system or blocking beta-receptors.', 'Pre-Council', '🎓', true),
(8807, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'This vasopressor drug is neurotransmitter and a hormone', '["Vasopressin", "Adrenaline", "Dopamine", "Dobutamine"]'::jsonb, 1, 'Adrenaline (epinephrine) uniquely functions both as a hormone secreted by the adrenal medulla into the bloodstream and as a neurotransmitter released at sympathetic nerve endings, unlike the other vasopressors listed.', 'Pre-Council', '🎓', true),
(8808, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All are indications of Adrenaline except one', '["Cardiac resuscitation", "Anaphylaxis", "Symptomatic bradycardia", "Heart failure"]'::jsonb, 2, 'Adrenaline is not the preferred agent for symptomatic bradycardia, where atropine or pacing is used instead; it is indicated for cardiac arrest resuscitation, anaphylaxis, and as an inotropic support in severe heart failure.', 'Pre-Council', '🎓', true),
(8809, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Poisoning is', '["Death only as a result of taking harmful substances", "Injury resulting from the contact, ingestion, of poisonous substances.", "Injury or death resulting from ingestion, inhalation, touching, injection of any substance.", "Drinking poison"]'::jsonb, 2, 'Poisoning is broadly defined as injury or death resulting from exposure to a harmful substance through any route, including ingestion, inhalation, skin contact, or injection, not just by drinking a toxic substance.', 'Pre-Council', '🎓', true),
(8810, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which is not true about Zopiclone?', '["Is a benzodiazepine sedative", "Is a benzodiazepine like sedative", "It acts by binding to benzodiazepine receptors", "Its use for a short period of time"]'::jsonb, 0, 'Zopiclone is not a benzodiazepine; it belongs to a chemically distinct class called cyclopyrrolones, or Z-drugs, even though it binds to the same benzodiazepine receptor site on the GABA-A complex and is intended for short-term use.', 'Pre-Council', '🎓', true),
(8811, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Routes of cyanide poisoning', '["Ingestion", "Inhaling", "All of the above", "None of the above"]'::jsonb, 2, 'Cyanide poisoning can occur through multiple routes, including ingestion of contaminated substances and inhalation of cyanide gas such as from smoke or industrial exposure, so all of the listed routes apply.', 'Pre-Council', '🎓', true),
(8812, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of these is not an antihypertensive', '["Valsartan", "Atenolol", "Hydrallazine", "None of the above"]'::jsonb, 3, 'Valsartan, atenolol, and hydralazine are all established antihypertensive agents, acting respectively through angiotensin receptor blockade, beta-blockade, and direct vasodilation, so none of them is the exception, making none of the above the correct choice.', 'Pre-Council', '🎓', true),
(8813, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Risk factors for drug overdose among adults include . History of mental disorder . Not knowing or following dosage instruction . Age . A and B only 70. The goals of treatment in hypertension are', '["To lower BP to a predetermined target", "To prevent organ damage", "All of the above", "To monitor the patient''s BP"]'::jsonb, 2, 'The goals of hypertension treatment include lowering blood pressure to an individualized target, preventing organ damage from sustained high pressure, and ongoing monitoring of the blood pressure of the patient, so all of these goals apply together.', 'Pre-Council', '🎓', true),
(8814, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Balanced Anaesthesia refers to:', '["Hypnosis, Muscle paralysis and analgesia", "Hypnosis, stable vital signs and analgesia", "Hypnosis, muscle relaxation and monitoring", "Hypnosis, Analgesia and Monitoring"]'::jsonb, 0, 'Balanced anaesthesia refers to the combined use of hypnosis (unconsciousness), muscle paralysis (relaxation for surgical access), and analgesia (pain control), using multiple agents together rather than one drug for all three effects.', 'Pre-Council', '🎓', true),
(8815, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All are intravenous Anaesthetic except:', '["Morphine", "Sodium thiopentone", "Ketamine", "Etomidate"]'::jsonb, 0, 'Sodium thiopentone, ketamine, and etomidate are all intravenous induction anaesthetic agents, whereas morphine is an opioid analgesic used for pain control rather than as a primary agent for inducing anaesthesia.', 'Pre-Council', '🎓', true),
(8816, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'One of the following can be used for both induction and maintenance of Anaesthesia:', '["Isoflurane", "Desflurane", "Sevoflurane", "Enflurane"]'::jsonb, 2, 'Sevoflurane has a pleasant, non-irritating smell and low blood solubility, making it suitable for both inhalational induction and maintenance of anaesthesia, unlike isoflurane, desflurane, and enflurane, which are pungent and mainly used for maintenance only.', 'Pre-Council', '🎓', true),
(8817, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All of the following are types of hypoxias except', '["Hypoxic hypoxia", "Histotoxic hypoxia", "Infectious hypoxia", "Circulatory hypoxia"]'::jsonb, 2, 'Recognized categories of hypoxia are hypoxic, histotoxic, circulatory (stagnant), and anaemic hypoxia, based on the underlying mechanism of impaired oxygen delivery or use. Infectious hypoxia is not a standard classification.', 'Pre-Council', '🎓', true),
(8818, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Regarding hypoxia choose the correct statement:', '["Refers to oxygen level in arterial blood measured in arterial blood gases", "Early signs of hypoxia include seizures, coma and arrythmias", "Diagnosis includes oxygen saturation level <94%, PaO2 > 80mmHg and urine output", "Oxygen saturation of <90% is an indication for oxygen therapy"]'::jsonb, 3, 'An oxygen saturation below 90 percent indicates significant hypoxemia and is generally accepted as a threshold warranting supplemental oxygen therapy, unlike the other listed statements, which misstate normal diagnostic thresholds or early signs of hypoxia.', 'Pre-Council', '🎓', true),
(8819, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Regarding Hypercarbia choose the correct statement:', '["Hypercarbia refers to elevated levels of carbon dioxide (CO2) in the arterial blood PaCO2 < 25mmHg.", "Causes of hypercarbia includes Opioids overdose, brain stem injury and COPD", "Treatment is always by mechanical ventilation", "If left untreated hypercarbia resolves spontaneously"]'::jsonb, 1, 'Hypercarbia, or elevated arterial carbon dioxide, can result from conditions that suppress or impair ventilation, such as opioid overdose, brainstem injury affecting the respiratory center, and chronic obstructive pulmonary disease, which limits effective gas exchange.', 'Pre-Council', '🎓', true),
(8820, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Clinical manifestation of hypercarbia includes the following except:', '["Tachypnoea", "Confusion and agitation", "Renal failure", "Headache"]'::jsonb, 2, 'Hypercarbia classically presents with tachypnoea as the body tries to compensate, along with confusion, agitation, and headache from cerebral vasodilation and rising carbon dioxide levels. Renal failure is not a direct clinical manifestation of hypercarbia.', 'Pre-Council', '🎓', true),
(8821, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Complication of hypercarbia include the following except', '["Respiratory failure", "Pulmonary hypertension", "Jaundice", "Cerebral oedema"]'::jsonb, 2, 'Untreated hypercarbia can progress to respiratory failure, pulmonary hypertension from vasoconstriction, and cerebral oedema due to increased cerebral blood flow, but jaundice is unrelated to elevated carbon dioxide levels.', 'Pre-Council', '🎓', true),
(8822, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Regarding central venous pressure (CVP):', '["Central venous pressure (CVP) is a crucial indicator of how well heart is pumping blood (measuring the pressure in the large veins)", "CVP is use to determine hydration status", "Measured in the SVC near the right atrium", "Normal value is 20-30cm H2O"]'::jsonb, 2, 'Central venous pressure is measured invasively via a catheter positioned in the superior vena cava close to the right atrium, reflecting right heart filling pressure rather than being measured elsewhere or noninvasively at that precision.', 'Pre-Council', '🎓', true),
(8823, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Choose the wrong statement regarding CVP:', '["Mechanical ventilation can increase CVP.", "Severe pain can cause CVP to rise.", "Certain medications can affect CVP", "CVP can only be measured invasively"]'::jsonb, 3, 'Central venous pressure can also be estimated noninvasively, such as by observing jugular venous distension, so the statement that it can only be measured invasively is false, making it the incorrect statement among the options.', 'Pre-Council', '🎓', true),
(8824, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Airway management is a priority in critical care nursing so as to maintain the following except', '["Electrolyte balance", "Ventilation", "Haemostasis", "Oxygenation"]'::jsonb, 2, 'Airway management in critical care primarily aims to maintain ventilation and oxygenation and preserve airway patency. Haemostasis, or control of bleeding, is a separate clinical priority unrelated to the core goals of airway management.', 'Pre-Council', '🎓', true),
(8825, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '-------------- is contraindicated to laryngeal mass airway (LMA)', '["General anaesthesia", "Abdominal surgery", "Operation on the lower limb", "Trismus"]'::jsonb, 3, 'Trismus, the inability to open the mouth adequately due to spasm of the jaw muscles, prevents proper insertion and seating of a laryngeal mask airway, making it a contraindication for its use.', 'Pre-Council', '🎓', true),
(8826, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Poor pulmonary compliance is', '["Indication of intubation", "Complication of delayed recovery", "Contraindication of LMA", "A good case for underwater seal drainage"]'::jsonb, 1, 'Reduced lung compliance impairs effective ventilation and gas exchange, which can slow emergence and prolong recovery from anaesthesia, making poor pulmonary compliance a recognized complication contributing to delayed recovery.', 'Pre-Council', '🎓', true),
(8827, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Arrange the following in sequence:', '["Induction of anaesthesia, premedication, pre anaesthetic assessment, pre anaesthetic visit.", "Induction, premedication, pre anaesthetic visit and pre anaesthetic assessment", "Induction of anaesthesia, premedication, pre anaesthetic visit and pre anaesthetic assessment", "Pre anaesthetic visit, pre anaesthetic assessment, induction and premedication E. Pre anaesthetic visit, pre anaesthetic assessment, premedication and induction"]'::jsonb, 3, 'The correct anaesthesia workflow proceeds from the pre-anaesthetic visit, to pre-anaesthetic assessment, then premedication, and finally induction of anaesthesia, ensuring the patient is properly evaluated and prepared before anaesthetic drugs are given.', 'Pre-Council', '🎓', true),
(8828, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All the following are indication for airway management except', '["Desaturation", "Respiratory distress", "Patient on spirometry", "Compromise airway"]'::jsonb, 2, 'Airway management is indicated when a patient shows desaturation, respiratory distress, or a compromised airway. Being on spirometry, a lung function test, is not itself an indication requiring airway intervention.', 'Pre-Council', '🎓', true),
(8829, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following patient does not require intubation ?', '["Patient for head and neck surgery", "Patient unable to maintain his airway", "Patient on tracheostomy", "Patient that need controlled ventilation"]'::jsonb, 2, 'A patient who already has a tracheostomy has a surgically established airway in place and does not require additional intubation, unlike patients needing airway protection, controlled ventilation, or undergoing head and neck surgery.', 'Pre-Council', '🎓', true),
(8830, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is not true', '["Oropharyngeal airway may stimulate coughing", "Oropharyngeal airway may provoke vomiting", "Oropharyngeal airway may cause laryngeal spasm", "Oropharyngeal airway may lead to desaturation"]'::jsonb, 3, 'A properly placed oropharyngeal airway helps maintain a patent airway and supports oxygenation rather than causing desaturation, though in a patient with an intact gag reflex it can trigger coughing, vomiting, or laryngeal spasm.', 'Pre-Council', '🎓', true),
(8831, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Choose the correct option', '["A moribund patient is contraindicated for surgery", "A moribund patient means a patient for emergency", "ASA classification guide the anaesthetist in the perioperative period", "ASA 1 patient means the patient does not require surgery"]'::jsonb, 2, 'The American Society of Anesthesiologists physical status classification helps the anaesthetist assess the baseline health of a patient and anticipate risk, guiding decisions and preparation throughout the perioperative period.', 'Pre-Council', '🎓', true),
(8832, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All are part of care of anaesthesia devise except', '["Regular cleaning", "Use of disinfectants on breathing circuit", "Ensure a functional scavenging system", "Use of glutaraldehyde is advocated"]'::jsonb, 3, 'Regular cleaning, appropriate disinfection of the breathing circuit, and correct use of agents like glutaraldehyde relate directly to cleaning and decontaminating the anaesthesia device. Ensuring a functional scavenging system is instead a separate operating room safety measure for removing waste anaesthetic gases.', 'Pre-Council', '🎓', true),
(8833, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'In the care of anaesthesia device ------- is not necessary', '["Regular cleaning", "Mechanical checking", "Ensure alternate oxygen source", "Cylinders should be fitted correctly"]'::jsonb, 3, 'Regular cleaning, mechanical checking, and having an alternate oxygen source available are ongoing care and safety practices for the anaesthesia machine, while correctly fitting cylinders is a one-time setup requirement rather than a recurring care activity.', 'Pre-Council', '🎓', false),
(8834, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Beliefs:', '["Is a tenets or convictions that people hold to be true", "Its shared", "Is both culturally and scientifically inclined", "All of the above"]'::jsonb, 3, 'Beliefs are tenets or convictions accepted as true, are typically shared among members of a group, and can be shaped by both cultural tradition and scientific reasoning, so all of these descriptions apply.', 'Pre-Council', '🎓', true),
(8835, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which option best describe culture:', '["It is the shared beliefs, practices, and material objects of a group of people.", "Ideal culture is real culture.", "Real culture is the ideal culture.", "Is about enforcing rewards or punishments in society"]'::jsonb, 0, 'Culture is best described as the shared beliefs, practices, and material objects (artifacts, tools, symbols) that characterize a group of people and are passed down and learned within that society.', 'Pre-Council', '🎓', true),
(8836, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All are true about culture except', '["It is a way of life of people", "Rewards and punishments are encourage in a society for social control", "social values are standard for discerning what is good and just in society", "None of the above"]'::jsonb, 3, 'Culture functions as a way of life, uses rewards and punishments to encourage social control, and provides social values as standards for judging what is good and just, so none of these statements is false, making none of the above correct.', 'Pre-Council', '🎓', true),
(8837, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'In the area of intelligence, WAIS stands for:', '["Wernicke Aphasic Intelligence Scale", "Wechsler Adult Intelligence Scale", "Wechsler Aptitude and Intelligence Scale", "Wernicke Approximate Intelligence Scale"]'::jsonb, 1, 'WAIS stands for Wechsler Adult Intelligence Scale, a standardized psychometric test developed by David Wechsler to measure intelligence in adults and older adolescents. It assesses verbal comprehension, working memory, perceptual reasoning, and processing speed to produce an overall IQ score.', 'Pre-Council', '🎓', true),
(8838, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Tangible and intangible culture is otherwise known as', '["Material Culture and Non Material Culture", "Material Country and Non Material Culture", "Manual Culture and Non Manual Culture", "Culture and Culture"]'::jsonb, 0, 'Tangible and intangible culture are commonly called material culture, meaning physical objects such as tools, clothing, and buildings, and non material culture, meaning values, beliefs, norms, and language. This distinction separates the physical products of a society from its abstract ideas and practices.', 'Pre-Council', '🎓', true),
(8839, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All the following are characteristics of culture except', '["Dynamic", "Continuous", "Competitive", "Varies"]'::jsonb, 2, 'Culture is dynamic, meaning it changes over time, continuous, meaning it is passed on across generations, and it varies from one society to another, but it is not inherently competitive. Competitiveness describes individual or group behavior, not a defining feature of culture itself.', 'Pre-Council', '🎓', true),
(8840, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Religion perform the following social function in a society except', '["legitimize power", "Unify all human societies", "Clarify the world", "Support in critical stage"]'::jsonb, 1, 'Religion legitimizes power, helps explain or clarify the world, and offers support during crises, but it does not unify all human societies since different religions often divide rather than unite groups worldwide. Religion typically integrates members within a particular society, not humanity as a whole.', 'Pre-Council', '🎓', true),
(8841, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Social classification can take the following dimension except', '["Economic", "Cultural", "Political", "Equality"]'::jsonb, 3, 'Social classification is commonly based on economic, cultural, and political dimensions that create hierarchies and stratification. Equality is not a dimension of classification; social classification usually reflects and produces inequality among groups rather than equality.', 'Pre-Council', '🎓', true),
(8842, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '________ Is the scholar that dominate the theory of social classification', '["Max Weber", "Karl Marx", "E. B. Dubois", "F. Tonnies"]'::jsonb, 1, 'Karl Marx is the scholar most associated with the theory of social classification, having developed the concept of social class based on ownership of the means of production, dividing society into the bourgeoisie and the proletariat.', 'Pre-Council', '🎓', true),
(8843, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Socialization is the process by which', '["people interact with one another.", "children, learn acceptable and unacceptable behaviors for a given environment.", "sum of social relations among humans in their immediate environment", "All of the above"]'::jsonb, 3, 'Socialization encompasses all these processes together, including people interacting with one another, children learning acceptable and unacceptable behaviors, and the sum of social relations in an immediate environment. It is the lifelong process through which individuals learn the norms and values of their society.', 'Pre-Council', '🎓', true),
(8844, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'How does patient feedback contribute to quality assurance in nursing practice?', '["It is not important for quality assurance", "It helps identify areas for improvement and promotes patient-centered care", "It increases nurse workload", "It discourages transparency"]'::jsonb, 1, 'Patient feedback highlights gaps in care delivery from the recipient perspective, allowing nurses and managers to pinpoint specific areas needing improvement while reinforcing a patient-centered approach to quality assurance. Ignoring feedback would undermine transparency and continuous quality improvement efforts.', 'Pre-Council', '🎓', true),
(8845, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'In a nursing audit, what does the term "non-compliance" refer to?', '["Adherence to standards and policies", "Inadequate staffing levels", "Failure to meet audit criteria", "High patient satisfactions"]'::jsonb, 2, 'In a nursing audit, non-compliance specifically refers to failure to meet established audit criteria or standards of care, such as missed documentation or unmet protocols. It is the opposite of adherence, which reflects compliance with policies.', 'Pre-Council', '🎓', true),
(8846, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Nursing theories play significant role in ...', '["Nursing Education", "Nursing  Practice", "Patient interaction", "a, b & c"]'::jsonb, 3, 'Nursing theories provide the conceptual foundation for nursing education curricula, guide clinical practice decisions, and shape how nurses interact with and understand patients, making all three areas correct together.', 'Pre-Council', '🎓', true),
(8847, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'play a significant role in Nursing Education, Practice and Patient interaction.', '["Nursing concept.", "Nursing theory", "Nursing research", "Nursing practice"]'::jsonb, 1, 'Nursing theory is the organized body of knowledge that guides and informs nursing education, clinical practice, and patient interaction, distinguishing it from broader nursing concepts, nursing research, or nursing practice alone.', 'Pre-Council', '🎓', true),
(8848, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Martha Rogers (1979) considers man as------------', '["Energy field", "The universe", "Unitary human being", "Man interact with the environment."]'::jsonb, 2, 'Martha Rogers (1979) described man as a unitary human being, an irreducible, indivisible whole that is more than and different from the sum of its parts, continuously interacting with the environment as an energy field.', 'Pre-Council', '🎓', true),
(8849, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '"Humanistic Sciences of Nursing", is a theory by;', '["Betty Neumann 1972.", "Sister Callista Roy''s 1979; Roy, 1980.", "Martha Rogers 1979.", "Orem''s self-care model"]'::jsonb, 2, 'Martha Rogers 1979 developed the Science of Unitary Human Beings, also referred to as a humanistic science of nursing, which views humans and their environment as integrated energy fields rather than separate entities.', 'Pre-Council', '🎓', true),
(8850, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'defined a total-person model incorporating the holistic concept and an open-systems approach.', '["Betty Neumann 1972.", "Martha Rogers 1979", "Orem''s self-care model", "Sister Callista Roy''s 1979; Roy, 1980."]'::jsonb, 0, 'Betty Neuman 1972 developed the Neuman Systems Model, a total-person approach that incorporates holistic concepts and an open-systems perspective, viewing the client as a system interacting with environmental stressors.', 'Pre-Council', '🎓', true),
(8851, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following Stressors that disrupt the system according Neumann''s model include ------ ------', '["The primary, secondary, and tertiary stressor.", "The individuals, families, and groups stressor", "Physiological, sociocultural, and developmental stressor", "Intra-personal, inter- personal, and extra personal stressors."]'::jsonb, 3, 'Neuman model identifies stressors as intra-personal, meaning within the person, inter-personal, meaning between individuals, and extra-personal, meaning outside the person such as environmental factors, all of which can disrupt system stability.', 'Pre-Council', '🎓', true),
(8852, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Sister Callista Roy''s adaptation theory (Roy, 1979; Roy, 1980) viewed the client as an', '["Adaptive system.", "Humanistic Sciences", "Open-systems approach.", "Unitary human being"]'::jsonb, 0, 'The Roy Adaptation Model (Roy, 1979, 1980) views the client as an adaptive system that responds to internal and external stimuli through coping mechanisms, aiming to maintain adaptation across physiological, self-concept, role function, and interdependence modes.', 'Pre-Council', '🎓', true),
(8853, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '---------------------------is goal of systems model of Nursing practice (Torres, 1986).', '["Stress response.", "Maintain maximal degree of health.", "Stress reduction", "Adaptive system."]'::jsonb, 2, 'Torres 1986 identified stress reduction as the goal of the systems model of nursing practice, since the model focuses on identifying and managing stressors that threaten stability and equilibrium in the client system.', 'Pre-Council', '🎓', true),
(8854, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is NOT a concept related to Roy''s Adaptation Model?', '["Focal Stimuli", "Cognator Subsystem", "Role function", "Flexible line of defense"]'::jsonb, 3, 'Flexible line of defense is a concept from the Neuman Systems Model, not the Roy Adaptation Model. The Roy model instead includes concepts such as focal stimuli, the cognator subsystem, and role function as adaptive modes.', 'Pre-Council', '🎓', true),
(8855, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which is NOT a concept explained in Dorothy Johnson''s Behavioral Systems Model?', '["Affiliation", "Dependency", "Achievement", "Energy fields"]'::jsonb, 3, 'Energy fields is a concept from Martha Rogers Science of Unitary Human Beings, not the Dorothy Johnson Behavioral Systems Model, which instead describes subsystems such as affiliation, dependency, and achievement.', 'Pre-Council', '🎓', true),
(8856, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'A theory is derived from a Greek word ''Thoeora'' signifying ...............', '["Vision", "Plan", "Focus", "mission"]'::jsonb, 0, 'The word theory derives from the Greek term theoria, which signifies vision or a way of seeing, reflecting how a theory provides a particular perspective or lens for understanding phenomena.', 'Pre-Council', '🎓', true),
(8857, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following are parts of component of Health Continuum EXCEPT', '["Physical health", "Emotional health", "Mental health", "Environmental health"]'::jsonb, 3, 'The health continuum typically includes physical, emotional, and mental health as interrelated components of overall wellbeing. Environmental health is considered an external determinant of health rather than a component of the personal health continuum itself.', 'Pre-Council', '🎓', true),
(8858, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The important determinant of health are EXCEPT', '["Environment", "life style", "Socio-economic condition", "Other factor"]'::jsonb, 3, 'Environment, lifestyle, and socio-economic condition are specific, well established determinants of health. Other factor is too vague and nonspecific to be classified as a recognized determinant, making it the exception among the named determinants.', 'Pre-Council', '🎓', true),
(8859, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Environmental theory was presented by Nightingale in ............', '["1859", "1857", "1862", "1860"]'::jsonb, 0, 'Florence Nightingale presented her Environmental Theory in 1859 in her work Notes on Nursing, emphasizing that a clean, well ventilated, and properly lit environment promotes healing and prevents disease.', 'Pre-Council', '🎓', true),
(8860, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'is basically defined as a tool or machine used for processing data  to give required information?', '["Printer", "Desktop", "Computer", "Mouse"]'::jsonb, 2, 'A computer is defined as a tool or machine that processes input data according to instructions to produce required output information. Printer and mouse are peripheral devices, while desktop refers only to one form factor of computer, not the general defining term.', 'Pre-Council', '🎓', true),
(8861, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The location of a resource on the internet is given by its?', '["Protocol", "URL", "E-mail address", "ICQ"]'::jsonb, 1, 'The location of a resource on the internet is given by its URL, or Uniform Resource Locator, which specifies the protocol, domain, and path needed to access that specific resource.', 'Pre-Council', '🎓', true),
(8862, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'is the most common internet protocol?', '["HTML", "NetBEUI", "TCP/IP", "IPX/SPX"]'::jsonb, 2, 'TCP/IP, or Transmission Control Protocol and Internet Protocol, is the most common and foundational protocol suite used for communication and data transfer across the internet, unlike HTML which is a markup language, not a protocol.', 'Pre-Council', '🎓', true),
(8863, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The term FTP stands for?', '["File transfer program", "File transmission protocol", "File transfer protocol", "File transfer protection"]'::jsonb, 2, 'FTP stands for File Transfer Protocol, a standard network protocol used to transfer files between a client and a server over a computer network such as the internet.', 'Pre-Council', '🎓', true),
(8864, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'is not a network topology?', '["Star", "Ring", "Bus", "Peer to Peer"]'::jsonb, 3, 'Star, ring, and bus are all physical or logical network topologies describing how devices are arranged and connected. Peer to peer describes a network architecture or relationship model, not a topology.', 'Pre-Council', '🎓', true),
(8865, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The term WAN stands for?', '["Wide Area Net", "Wide Access Network", "Wide Area Network", "Wide Access Net"]'::jsonb, 2, 'WAN stands for Wide Area Network, a telecommunications network that extends over a large geographic area, connecting multiple smaller local networks such as LANs across cities or countries.', 'Pre-Council', '🎓', true),
(8866, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The term LAN stands for?', '["Local Area .News", "Local Area Network", "Local Array Network", "Local Array Netcom"]'::jsonb, 1, 'LAN stands for Local Area Network, a network that connects computers and devices within a limited geographic area such as a single building or office.', 'Pre-Council', '🎓', true),
(8867, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is not an input device?', '["Keyboard", "Mouse", "Speaker", "Scanner"]'::jsonb, 2, 'A speaker is an output device because it converts electronic signals into audible sound for the user, whereas keyboards, mice, and scanners are all input devices that send data into the computer.', 'Pre-Council', '🎓', true),
(8868, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following is an example of internet browser?', '["Microsoft Word", "Notepad", "Internet navigator", "Internet explorer"]'::jsonb, 3, 'Internet Explorer is a web browser used to access and display content on the internet. Microsoft Word and Notepad are word processing and text editing applications, not browsers.', 'Pre-Council', '🎓', true),
(8869, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'A process simply means a _______.', '["single thread of execution.", "program in the execution", "program in the memory", "task"]'::jsonb, 1, 'A process is defined as a program in execution, meaning the operating system has loaded the program into memory and is actively running its instructions, distinguishing it from a program merely stored on disk.', 'Pre-Council', '🎓', true),
(8870, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'These are risks of parenteral nutrition EXCEPT', '["Infection", "Hyperglycaemia", "Hypoglycaemia", "Vomiting"]'::jsonb, 3, 'Infection, hyperglycaemia, and hypoglycaemia are recognized risks of parenteral nutrition due to the intravenous route and metabolic load of the solution. Vomiting is not a typical parenteral nutrition risk since the therapy bypasses the gastrointestinal tract entirely.', 'Pre-Council', '🎓', true),
(8871, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'These are types of enteral feeding EXCEPT', '["Nasogastric tube", "Orogastric  tube", "Peripheral parenteral nutrition", "Jejunostomy tube"]'::jsonb, 2, 'Peripheral parenteral nutrition delivers nutrients directly into the bloodstream through a vein, bypassing the gastrointestinal tract, so it is a form of parenteral, not enteral, feeding. Nasogastric, orogastric, and jejunostomy tubes all deliver nutrition into the gut.', 'Pre-Council', '🎓', true),
(8872, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Food at work in the body can be defined as:', '["nutrients", "science", "nutrition", "food function"]'::jsonb, 2, 'Nutrition is defined as food at work in the body, encompassing the processes by which the body takes in and utilizes food for growth, energy, and maintenance of health.', 'Pre-Council', '🎓', true),
(8873, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Nutrients can be broadly classified as:', '["important & unimportant", "essential & non-essential", "macro & micro", "basic and complex."]'::jsonb, 2, 'Nutrients are broadly classified as macronutrients, such as carbohydrates, proteins, and fats needed in large amounts, and micronutrients, such as vitamins and minerals needed in small amounts, reflecting the quantity required by the body.', 'Pre-Council', '🎓', true),
(8874, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'One example of nutrients needed in large amount in the body', '["vitamin C", "lipids", "iron", "energy"]'::jsonb, 1, 'Lipids are macronutrients required in relatively large amounts to supply energy, support cell membrane structure, and enable absorption of fat soluble vitamins, unlike micronutrients such as vitamin C or iron which are needed only in small quantities.', 'Pre-Council', '🎓', true),
(8875, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'One example of nutrients needed in small amount in the body', '["Protein", "Glucose", "Mineral", "iodine"]'::jsonb, 3, 'Iodine is a trace mineral, or micronutrient, needed only in very small amounts, primarily for thyroid hormone synthesis, unlike macronutrients such as protein or glucose which are required in much larger quantities.', 'Pre-Council', '🎓', true),
(8876, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'One of these is energy-yielding nutrient', '["lipids", "iron", "calorie", "folate"]'::jsonb, 0, 'Lipids are an energy yielding nutrient, providing the body with a concentrated source of energy at about nine kilocalories per gram, unlike iron and folate which are micronutrients that do not directly yield energy.', 'Pre-Council', '🎓', true),
(8877, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Fat soluble vitamins are how many in numbers?', '["5", "4", "3", "2"]'::jsonb, 1, 'There are four fat soluble vitamins, A, D, E, and K. These vitamins dissolve in fat and are stored in body fat and the liver, unlike water soluble vitamins which are not stored to the same extent.', 'Pre-Council', '🎓', true),
(8878, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Water soluble vitamins are how many in numbers?', '["7", "8", "9", "10"]'::jsonb, 2, 'There are nine water soluble vitamins, vitamin C and the eight B complex vitamins, including B1, B2, B3, B5, B6, B7, B9, and B12. These vitamins dissolve in water and are not stored significantly, requiring regular dietary intake.', 'Pre-Council', '🎓', true),
(8879, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The first pathway glucose takes on its way to yield energy is called', '["Glucolysis", "Glycosides", "Glycogenolysis", "glycolysis"]'::jsonb, 3, 'Glycolysis is the first pathway glucose undergoes to yield energy, breaking glucose down into pyruvate in the cell cytoplasm before it proceeds to further pathways such as the Krebs cycle for additional ATP production.', 'Pre-Council', '🎓', true),
(8880, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All these are characteristics of inorganic nutrient EXCEPT', '["easily digested", "absorbed as-it-is", "cannot be destroyed", "cannot be created."]'::jsonb, 0, 'Inorganic nutrients such as minerals are absorbed as is without being chemically broken down, so unlike organic nutrients they are not easily digested. They also cannot be created or destroyed, only rearranged, distinguishing them from organic nutrients.', 'Pre-Council', '🎓', true),
(8881, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All the changes that occur in the food from the time we eat it, to its use in the body and discarding of the waste matter are known as:', '["food process", "absorption", "metabolism", "catabolism."]'::jsonb, 2, 'Metabolism refers to all the chemical changes that occur in food from ingestion through its use in the body and the eventual elimination of waste products, encompassing both anabolic and catabolic processes.', 'Pre-Council', '🎓', true),
(8882, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Generally the use of food in the body involves how many processes?', '["1", "2", "3", "4"]'::jsonb, 2, 'The use of food in the body generally involves three processes, digestion which breaks food down, absorption which takes nutrients into the blood, and metabolism which is the cellular utilization of those nutrients.', 'Pre-Council', '🎓', true),
(8883, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'During digestion, food passes from the mouth to the stomach via the oesophagus, how many sphincter muscles are involved in the oesophagus?', '["1", "2", "3", "4"]'::jsonb, 1, 'The esophagus involves two sphincter muscles, the upper esophageal sphincter and the lower esophageal sphincter, which control passage of food from the pharynx into the esophagus and from the esophagus into the stomach.', 'Pre-Council', '🎓', true),
(8884, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The series of wave-like muscle contractions that move food through the GI tract is known as', '["Peristalsis", "Bolus", "Hemostasis", "digestive movement"]'::jsonb, 0, 'Peristalsis refers to the coordinated, wave like muscular contractions that propel food along the gastrointestinal tract, from the esophagus through the stomach and intestines, enabling digestion and movement of contents.', 'Pre-Council', '🎓', true),
(8885, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The breakdown of food into nutrients requires secretions from how many different organs?', '["6", "7", "5", "4"]'::jsonb, 2, 'Breaking down food into absorbable nutrients requires secretions from five organs, the salivary glands, stomach, liver, pancreas, and small intestine, each contributing enzymes or fluids essential for digestion.', 'Pre-Council', '🎓', true),
(8886, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The gastric juice is a mixture of how many components?', '["3", "2", "4", "1"]'::jsonb, 0, 'Gastric juice is generally described as a mixture of three main components, hydrochloric acid, pepsin, a digestive enzyme, and mucus, which together break down food and protect the stomach lining.', 'Pre-Council', '🎓', true),
(8887, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The process of sucking up the nutrients in the body is known as:', '["Assimilation", "Utilization", "Absorption", "digestion."]'::jsonb, 2, 'Absorption is the process by which digested nutrients are taken up through the intestinal wall into the bloodstream or lymphatic system for use by the body cells.', 'Pre-Council', '🎓', true),
(8888, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '------------- and ------------- of intestinal wall also affects absorption of final products of digestion.', '["temperature & Ph", "single & multiples", "length & width", "shape & size"]'::jsonb, 3, 'The shape and size of the intestinal wall, including its surface area created by folds, villi, and microvilli, directly affect how efficiently the final products of digestion are absorbed into the blood.', 'Pre-Council', '🎓', true),
(8889, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'During digestion, the body breaks down the three energy yielding nutrients into ------- basic units that can be absorbed into the blood.', '["6", "5", "4", "3"]'::jsonb, 2, 'During digestion, the three energy yielding nutrients are broken down into four basic absorbable units, glucose from carbohydrates, amino acids from proteins, and fatty acids and glycerol from fats.', 'Pre-Council', '🎓', true),
(8890, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following are reasons for research communication EXCEPT', '["Strengthen research capacity", "Improve the dissemination and repackaging of research for continuing knowledge.", "Strengthen the networking between researchers", "Enhance research funding"]'::jsonb, 3, 'Research communication aims to strengthen research capacity, improve dissemination of findings, and build networks among researchers, but enhancing research funding is an indirect benefit rather than a core stated reason for research communication itself.', 'Pre-Council', '🎓', true),
(8891, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following are Not contained in Research title EXCEPT', '["Abbreviations,", "Proprietary names", "Keywords", "Acronym"]'::jsonb, 2, 'A good research title should contain descriptive keywords that reflect the content of the study, while abbreviations, proprietary or brand names, and acronyms should be avoided because they can confuse readers or limit indexing and searchability.', 'Pre-Council', '🎓', true),
(8892, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which is a usual criterion for abstract, it should......', '["Not exceed 200-250 words", "Not exceed 251-300 words", "Not exceed 301-350 words", "Not exceed 351-400 words"]'::jsonb, 0, 'A standard criterion for a research abstract is that it should not exceed 200 to 250 words, keeping it concise while still summarizing the objective, methods, results, and conclusion of the study.', 'Pre-Council', '🎓', true),
(8893, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Abstract should be in......', '["Three paragraphs", "Two and half paragraphs", "One paragraph", "One and half paragraph E. Three and half paragraphs"]'::jsonb, 2, 'An abstract is conventionally written as a single continuous paragraph that succinctly summarizes the entire study, rather than being broken into multiple paragraphs the way the main body of the paper is.', 'Pre-Council', '🎓', true),
(8894, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Abstract should be written in the......', '["Present future tenses", "Past tenses", "Present tenses", "Past participle tenses"]'::jsonb, 1, 'An abstract is written in the past tense because it summarizes a study that has already been completed, including the methods used and the results obtained.', 'Pre-Council', '🎓', true),
(8895, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Results section is written in the............', '["Present future tenses", "Past tenses", "Present tenses", "Past participle tenses"]'::jsonb, 1, 'The results section of a research paper is written in the past tense because it reports findings from data that has already been collected and analyzed.', 'Pre-Council', '🎓', true),
(8896, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Result is the ........... of the research paper', '["Core", "Foundation", "Conclusion", "Summary"]'::jsonb, 0, 'The results section is considered the core of a research paper because it presents the actual findings and evidence generated by the study, forming the basis for the discussion and conclusions that follow.', 'Pre-Council', '🎓', true),
(8897, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The hardest section to write in research is?', '["Statement of problems", "Hypothesis", "Discussion of major findings", "Results"]'::jsonb, 2, 'The discussion of major findings is often considered the hardest section to write because it requires interpreting results, relating them to existing literature, explaining their significance, and addressing limitations in a coherent way.', 'Pre-Council', '🎓', true),
(8898, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Research means all the following.............. EXCEPT', '["To harmonize", "To re-examine", "To investigate", "To test"]'::jsonb, 0, 'Research generally means to investigate, re-examine, or test something systematically in search of truth or new knowledge. To harmonize is not part of the standard definition of research.', 'Pre-Council', '🎓', true),
(8899, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Process of research means the following EXCEPT', '["Identifying a problem", "Defining the problem in precise terms in unambiguous terms", "Making policies", "Designing the research"]'::jsonb, 2, 'The research process includes identifying a problem, defining it precisely and unambiguously, and designing the study methodology. Making policies is an application or outcome that may follow research, not a step within the research process itself.', 'Pre-Council', '🎓', true),
(8900, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '____________ refers to the element from which samples are specifically chosen or selected for research.', '["Finite population", "Target population", "Infinite population", "Sampling population"]'::jsonb, 1, 'The target population refers to the entire group of elements from which a sample is specifically selected for a study, representing the population to which the researcher intends to generalize findings.', 'Pre-Council', '🎓', true),
(8901, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'A member of population is called:', '["Element", "Data", "Family", "Group"]'::jsonb, 0, 'An element is the term used to describe a single member or unit of a population, such as one individual patient within a study population.', 'Pre-Council', '🎓', true),
(8902, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The population to be sampled is divided into units which are known as:', '["Sampling frame", "Sampling errors", "Sampling gap", "Sampling units"]'::jsonb, 3, 'The population being sampled is divided into distinct units called sampling units, which serve as the basis for selecting a representative sample, such as individual patients, wards, or households.', 'Pre-Council', '🎓', true),
(8903, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following are step in sampling process:', '["Defining target population", "Selecting and identifying the sample method", "Choosing sampling frame", "All of the above"]'::jsonb, 1, 'Selecting and identifying the appropriate sampling method is a critical step within the sampling process, ensuring the chosen technique matches the research objectives and population characteristics before actual sample selection occurs.', 'Pre-Council', '🎓', true),
(8904, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Population value is called', '["Parameter", "Statistic", "Variable", "Data"]'::jsonb, 0, 'A population value, such as the true mean or proportion of an entire population, is called a parameter, as opposed to a statistic, which describes a value calculated from a sample.', 'Pre-Council', '🎓', true),
(8905, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'A complete survey of population is called', '["Census", "Sample", "Report", "None of the above"]'::jsonb, 0, 'A census is a complete survey that collects data from every single member of a population, as opposed to a sample survey which examines only a subset.', 'Pre-Council', '🎓', true),
(8906, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Non-probability sampling is used with the aim of:', '["Qualitative Research", "Pilot studies", "Exploratory Research", "All of the above"]'::jsonb, 3, 'Non-probability sampling is commonly used for qualitative research, pilot studies, and exploratory research because it does not require a random, representative sample and is well suited to generating preliminary insights or in depth understanding.', 'Pre-Council', '🎓', true),
(8907, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Sampling errors is present only in:', '["Census survey", "Sample survey", "Both a and b", "None of the  above"]'::jsonb, 1, 'Sampling error, the difference between a sample statistic and the true population parameter, occurs only in sample surveys because a census examines the entire population, leaving no error attributable to sampling.', 'Pre-Council', '🎓', true),
(8908, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'As the sample size increase, the sampling error also:', '["Increase", "Decrease", "Constant", "Non- of the above"]'::jsonb, 1, 'As sample size increases, sampling error decreases because a larger sample more closely approximates the characteristics of the entire population, reducing the variability between the sample statistic and the true parameter.', 'Pre-Council', '🎓', true),
(8909, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Research is:', '["Searching again and again", "Finding solution to any problem", "Working in a scientific way to search for truth of any problem", "None of the above"]'::jsonb, 2, 'Research is best defined as working in a scientific, systematic way to search for the truth about a problem, involving careful investigation, data collection, and analysis rather than casual searching.', 'Pre-Council', '🎓', true),
(8910, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The commonly adopted positions in ICU/CCU include the following EXCEPT', '["Prone", "Cardiac", "Lithotomy", "Standing"]'::jsonb, 3, 'Prone, cardiac, and lithotomy positions are commonly used in ICU and CCU for various procedures and patient conditions, but standing is not a position used for critically ill, typically immobile patients in these units.', 'Pre-Council', '🎓', true),
(8911, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Unconsciousness include all the following EXCEPT', '["A state of abnormal cerebral activity", "Unresponsive to internal and external environmental changes", "Depression of cerebral function", "Awareness of self and environment"]'::jsonb, 3, 'Unconsciousness is characterized by abnormal cerebral activity, depressed cerebral function, and unresponsiveness to internal and external stimuli. Awareness of self and environment is the opposite of unconsciousness, describing a conscious state instead.', 'Pre-Council', '🎓', true),
(8912, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following are criteria for CCU admission EXCEPT', '["Post cardiac arrest", "Chronic renal failure", "Myocardiac infarction", "Prolong surgery"]'::jsonb, 1, 'Post cardiac arrest, myocardial infarction, and prolonged surgery are acute, life threatening conditions warranting CCU admission. Chronic renal failure, being a stable long term condition unless acutely decompensated, is not by itself a standard CCU admission criterion.', 'Pre-Council', '🎓', true),
(8913, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'It is essential that critical care services be the following EXCEPT', '["efficient", "effective", "Comfortable", "Affordable"]'::jsonb, 2, 'Critical care services must be efficient, effective, and affordable to ensure appropriate resource use and access, but comfortable is not typically listed as an essential quality standard for critical care service delivery.', 'Pre-Council', '🎓', true),
(8914, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Intensive Care Unit started in .....', '["1930s", "1940s", "1950s", "1960s"]'::jsonb, 2, 'Intensive Care Units began developing in the 1950s, notably following the Copenhagen polio epidemic of 1952 to 1953, which demonstrated the value of concentrating ventilatory and nursing support for critically ill patients in one unit.', 'Pre-Council', '🎓', true),
(8915, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The following are history areas you will assess during patients assessment EXCEPT', '["Past history", "Present history", "Detailed Educational history", "Medical history"]'::jsonb, 2, 'Patient assessment includes past history, present history, and medical history to understand the clinical picture, but a detailed educational history is not a relevant or standard component of a clinical patient assessment.', 'Pre-Council', '🎓', true),
(8916, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The ideal instrument for examining the pupils for size and reaction is..', '["pen torch light", "pupillary reaction light", "Touch reaction light", "Sluggish reacting light"]'::jsonb, 0, 'A pen torch light is the ideal simple instrument for examining pupil size and reaction to light at the bedside, allowing quick assessment of pupillary response as part of neurological examination.', 'Pre-Council', '🎓', true),
(8917, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Airway obstruction is diagnosed via the following EXCEPT', '["Gurgling", "Snoring", "Drooling of saliva", "Stridor"]'::jsonb, 2, 'Gurgling, snoring, and stridor are classic audible signs indicating airway obstruction from secretions, tongue relaxation, or narrowing. Drooling of saliva may accompany obstruction but is not itself a diagnostic sign of airway obstruction the way these sounds are.', 'Pre-Council', '🎓', true),
(8918, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'The percentage of CCU bed to the hospital bed is...', '["0.5-1%", "1-1.5%", "1-2%", "2-3%"]'::jsonb, 2, 'Critical care unit beds typically make up about 1 to 2 percent of total hospital beds, reflecting the resource intensive nature of critical care compared to general ward care.', 'Pre-Council', '🎓', true),
(8919, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Coughing during suctioning indicates stimulation of cough reflex centre at the', '["Larynx", "Pharynx", "Trachea", "Carina"]'::jsonb, 3, 'Coughing during suctioning indicates stimulation of the cough reflex centre located at the carina, the point where the trachea bifurcates into the two main bronchi, which is highly sensitive to mechanical stimulation.', 'Pre-Council', '🎓', true),
(8920, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Muscle relaxants are divided into two.....', '["short and intermediate acting", "long and short acting", "Short and induction", "Pre-med and induction agents"]'::jsonb, 1, 'Muscle relaxants used in anaesthesia are broadly divided into long acting and short acting agents based on their duration of neuromuscular blockade, which guides their selection for different procedures.', 'Pre-Council', '🎓', true),
(8921, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All of the following are Characteristics of a Good Documentation EXCEPT.', '["Factual & Accurate", "Clear & Complete", "Logical & Skillful", "Timely & Organized."]'::jsonb, 2, 'Good documentation should be factual and accurate, clear and complete, and timely and organized. Logical and skillful is not a standard recognized characteristic used to describe quality nursing documentation.', 'Pre-Council', '🎓', true),
(8922, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Patients that are admitted into Intensive Care Unit, should be ..', '["Reversible and irreversible", "Actual and Risk", "Critical and Reversible", "Actual and Well"]'::jsonb, 2, 'Patients admitted to the Intensive Care Unit should be critically ill but have a reversible condition, meaning they require intensive monitoring and support with a reasonable chance of recovery, distinguishing ICU admission from care for irreversible or terminal conditions.', 'Pre-Council', '🎓', true),
(8923, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'All the following are purpose of Documentation EXCEPT', '["Enhance good communication between healthcare professionals", "A guide for reimbursement of care cost", "For school evaluations", "Supports delivery and continuity of patient care"]'::jsonb, 2, 'Documentation enhances communication between healthcare professionals, supports reimbursement processes, and ensures continuity of patient care. It is not intended for school evaluations, which fall outside the clinical and administrative purposes of patient records.', 'Pre-Council', '🎓', true),
(8924, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', '------------- is a medical condition which occurs due to electrical disturbance in the brain', '["Convulsion", "Seizures", "a and b", "none of the above"]'::jsonb, 2, 'Convulsion and seizure both describe a medical condition arising from abnormal, excessive electrical discharges in the brain, with the terms often used interchangeably to refer to the resulting involuntary movements or altered consciousness.', 'Pre-Council', '🎓', true),
(8925, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Which of the following determines that patient no longer needs a chest tube', '["Chest x-ray shows a deflated lung of 35%", "Lots of drain is observed from the chest tube", "The underwater-sealed chamber does not fluctuate", "Arterial blood gases levels are observed to be normal"]'::jsonb, 2, 'When the underwater sealed drainage chamber no longer fluctuates with respiration, it indicates the lung has fully re-expanded and there is no further air leak, showing that the chest tube is no longer needed.', 'Pre-Council', '🎓', true),
(8926, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Only one of these is not related to Tetanus', '["Acute onset", "Hypotonia", "Muscular contractions", "Generalized spasms"]'::jsonb, 1, 'Tetanus is characterized by acute onset, muscular contractions, and generalized spasms due to toxin mediated hyperexcitability of motor neurons, causing rigidity and hypertonia rather than hypotonia, making hypotonia unrelated to the disease.', 'Pre-Council', '🎓', true),
(8927, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Usual routes of entry of Clostridium tetani include all of the following EXCEPT', '["Apparently trivial wound", "Through the oral cavity", "Human bites", "Fractures"]'::jsonb, 1, 'Clostridium tetani spores typically enter the body through contaminated wounds, such as apparently trivial wounds, human bites, or fractures exposed to soil or rust, thriving in anaerobic tissue. The oral cavity is not a typical route since the organism needs an anaerobic wound environment, not ingestion.', 'Pre-Council', '🎓', true),
(8928, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Post-procedure management of the patient with chest tube and underwater seal drainage system include all except', '["Obtain a chest radiograph", "Clamp the tube prior to changing the underwater seal drainage or transporting the patient", "Ensure rapid drainage of the collection", "Ensure adequate analgesics"]'::jsonb, 2, 'Post-procedure chest tube management includes obtaining a chest radiograph, clamping the tube only briefly when changing the drainage system or transporting the patient, and ensuring adequate analgesia. Drainage should occur gradually rather than rapidly, since rapid drainage of a large collection can cause re-expansion pulmonary edema.', 'Pre-Council', '🎓', true),
(8929, 'AEFUTHA Paper I, August 2025', 'AEFUTHA CCN Pre-Professional Exam, Paper I, August 2025 (uploaded past-paper set)', 'Complications of chest tube insertion include the following except', '["Injury to the lungs", "Esophageal injury", "Liver injury", "Pulmonary embolism Good Luck!!!"]'::jsonb, 1, 'Chest tube insertion can injure the lungs or, depending on site, the liver or spleen, and can be associated with pulmonary embolism related complications, but esophageal injury is not a recognized complication since the esophagus is not anatomically at risk during standard chest tube placement.', 'Pre-Council', '🎓', true);
